mapper.select:
		   select o.orgname as Staffidname,ds.realname as Staffdeptname,org.orgname as orgname,u.ORGNAME as staffunitname,r.*  from TBL_RISK_REVIEW  r
				 left join tbl_organization o on o.orgid=r.Staffdept
				  left join tbl_organization org on org.orgid=r.linkorgid
				 left join tbl_staff ds on ds.staffid=r.Staffid
				 left join tbl_organization u on u.orgid=r.STAFFUNIT
				  where 1=1 

				     and mattername LIKE concat(concat('%',#{queryParam.mattername} ),'%')


				   and mattercode LIKE concat(concat('%',#{queryParam.mattercode} ),'%')


				   and riskreviewcode LIKE concat(concat('%',#{queryParam.riskreviewcode} ),'%')


				   and u.orgname =#{queryParam.staffunitname}


				   and r.linkorgid =#{queryParam.linkorgid}




				      and  state  is null or state=''


				       and   state=#{queryParam.state}




				     and linkorgid=#{queryParam.linkorgid}

				   ${sql}
     order by createtime  desc
